        iconHolder.innerHTML = "&#9650;"; 
      }
    });
  });
  document.addEventListener("DOMContentLoaded", function () {
    const button = document.querySelector(".bt_bb_link_7");
    const content = document.getElementById("content_7");
	const buttonText = button.querySelector(".bt_bb_button_text");
	const iconHolder = button.querySelector(".bt_bb_icon_holder");
    button.addEventListener("click", function (e) {
      e.preventDefault(); // Ngăn trình duyệt chuyển hướng
      content.classList.toggle("hide");
	  if (content.classList.contains("hide")) {
        buttonText.textContent = "Xem thêm";
        iconHolder.innerHTML = "&#9660;"; 
      } else {
        buttonText.textContent = "Thu gọn";
        iconHolder.innerHTML = "&#9650;"; 
      }
    });
  });
</script>		 
